// Validate incoming payload from JS-15 or /api/n8n/cascade-trigger
const body = $input.first().json.body || $input.first().json;
const blood_request_id = body.blood_request_id;
const urgency = body.urgency || 'routine';

if (!blood_request_id) {
  throw new Error('Missing blood_request_id in cascade trigger payload');
}

if (!['routine', 'urgent', 'critical'].includes(urgency)) {
  throw new Error(`Invalid urgency: ${urgency}. Must be routine|urgent|critical`);
}

return [{ json: { blood_request_id, urgency } }];

// Check if blood request is already fulfilled before Tier 2
// Reads blood_requests row and checks donors_confirmed_count >= units_needed
const blood_request_id = $json.blood_request_id;
const urgency = $json.urgency;
const API_BASE = $env.API_BASE_URL || 'https://wb-grievance-portal.vercel.app';
const SECRET = $env.N8N_WEBHOOK_SECRET;

try {
  const res = await fetch(`${API_BASE}/api/blood-requests/${blood_request_id}`, {
    headers: { 'X-N8N-SECRET': SECRET }
  });
  const data = await res.json();
  const req = data.data || data;

  if (req.donors_confirmed_count >= req.units_needed) {
    // Fulfilled — stop cascade
    return [];
  }

  return [{ json: { blood_request_id, urgency, tier: 2, scope: 'block', count: 5, blood_group: req.blood_group, district: req.district, block: req.block, units_needed: req.units_needed } }];
} catch (err) {
  // On error, continue cascade (fail-open for donor safety)
  return [{ json: { blood_request_id, urgency, tier: 2, scope: 'block', count: 5 } }];
}

// Tier 2 (routine): next 5 same-block donors
// Internal sequence:
// 1. Read blood_requests row (fulfilled check done in prior node)
// 2. Read cascade_notifications (already-notified set)
// 3. Call find_matching_donors (exclude notified)
// 4. Slice top-5 for this tier
// 5. INSERT cascade_notifications rows ON CONFLICT DO NOTHING
// 6. INSERT blood_donor_responses (pending)
// 7. Send WhatsApp HAAN/NAHI buttons
// 8. UPDATE blood_requests cascade_tier = 2

const { blood_request_id, urgency, blood_group, district, block, units_needed } = $json;
const API_BASE = $env.API_BASE_URL || 'https://wb-grievance-portal.vercel.app';
const SECRET = $env.N8N_WEBHOOK_SECRET;
const TIER = 2;
const COUNT = 5;
const SCOPE = 'block';

try {
  // Find matching donors excluding already-notified
  const findRes = await fetch(`${API_BASE}/api/blood-requests/find-donors`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'X-N8N-SECRET': SECRET },
    body: JSON.stringify({ blood_request_id, scope: SCOPE, exclude_notified: true, limit: COUNT })
  });
  const donors = (await findRes.json()).data || [];

  if (donors.length === 0) {
    return [{ json: { blood_request_id, urgency, tier: TIER, donors_notified: 0 } }];
  }

  // Insert cascade_notifications + blood_donor_responses + send WhatsApp
  const notifyRes = await fetch(`${API_BASE}/api/n8n/cascade-notify-batch`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'X-N8N-SECRET': SECRET },
    body: JSON.stringify({ blood_request_id, tier: TIER, donor_ids: donors.map(d => d.id) })
  });

  // Update cascade_tier
  await fetch(`${API_BASE}/api/blood-requests/update-cascade-tier`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'X-N8N-SECRET': SECRET },
    body: JSON.stringify({ blood_request_id, cascade_tier: TIER })
  });

  return [{ json: { blood_request_id, urgency, tier: TIER, donors_notified: donors.length, completed: true } }];
} catch (err) {
  return [{ json: { blood_request_id, urgency, tier: TIER, error: err.message } }];
}

